   738→    <script>
   739→        // Mobile sidebar toggle
   740→        function toggleSidebar() {
   741→            document.getElementById('sidebar').classList.toggle('open');
   742→            document.getElementById('sidebarOverlay').classList.toggle('open');
   743→        }
   744→
   745→        function closeSidebar() {
   746→            document.getElementById('sidebar').classList.remove('open');
   747→            document.getElementById('sidebarOverlay').classList.remove('open');
   748→        }
   749→
   750→        // Toggle user-only message filter
   751→        let userOnlyMode = false;
   752→
   753→        function toggleUserOnly() {
   754→            userOnlyMode = !userOnlyMode;
   755→            const toggle = document.getElementById('userOnlyToggle');
   756→            const container = document.getElementById('messagesContainer');
   757→
   758→            if (userOnlyMode) {
   759→                toggle.classList.add('active');
   760→                container.classList.add('user-only');
   761→                // Collapse all expansions when entering user-only mode
   762→                collapseAllUserMessages();
   763→            } else {
   764→                toggle.classList.remove('active');
   765→                container.classList.remove('user-only');
   766→                // Clean up expanded classes
   767→                collapseAllUserMessages();
   768→            }
   769→        }
   770→
   771→        function collapseAllUserMessages() {
   772→            document.querySelectorAll('.message.user.expanded').forEach(el => el.classList.remove('expanded'));
   773→            document.querySelectorAll('.message.expanded-child').forEach(el => el.classList.remove('expanded-child'));
   774→        }
   775→
   776→        function toggleUserMessageExpansion(userMsgEl) {
   777→            if (!userOnlyMode) return;
   778→
   779→            const wasExpanded = userMsgEl.classList.contains('expanded');
   780→
   781→            // Collapse all first
   782→            collapseAllUserMessages();
   783→
   784→            if (wasExpanded) {
   785→                // Just collapse, don't re-expand
   786→                return;
   787→            }
   788→
   789→            // Expand this user message and show all following messages until next user message
   790→            userMsgEl.classList.add('expanded');
   791→
   792→            let nextEl = userMsgEl.nextElementSibling;
   793→            while (nextEl && !nextEl.classList.contains('user')) {
   794→                nextEl.classList.add('expanded-child');
   795→                nextEl = nextEl.nextElementSibling;
   796→            }
   797→        }
   798→
   799→        let projects = [];
   800→        let currentProject = null;
   801→        let conversations = {};
   802→        let currentConversation = null;
   803→        let currentMessage = null;
   804→
   805→        const listContainer = document.getElementById('listContainer');
   806→        const messagesContainer = document.getElementById('messagesContainer');
   807→        const conversationHeader = document.getElementById('conversationHeader');
   808→
   809→        // URL state management - use short project names in URLs
   810→        function getShortProjectName(fullName) {
   811→            const match = fullName.match(/-Desktop-(.+)$/);
   812→            return match ? match[1] : fullName.split('-').pop();
   813→        }
   814→
   815→        function getFullProjectName(shortName) {
   816→            // Find project by short name
   817→            const project = projects.find(p => getShortProjectName(p.name) === shortName);
   818→            return project ? project.name : shortName;
   819→        }
   820→
   821→        function updateUrl() {
   822→            const params = new URLSearchParams();
   823→            if (currentProject) params.set('project', getShortProjectName(currentProject));
   824→            if (currentConversation) params.set('session', currentConversation);
   825→            if (currentMessage) params.set('msg', currentMessage);
   826→            const newUrl = params.toString() ? `?${params.toString()}` : window.location.pathname;
   827→            history.pushState({project: currentProject, session: currentConversation, message: currentMessage}, '', newUrl);
   828→        }
   829→
   830→        function loadFromUrl() {
   831→            const params = new URLSearchParams(window.location.search);
   832→            const project = params.get('project');
   833→            const session = params.get('session');
   834→            const message = params.get('msg');
   835→            return { project, session, message };
   836→        }
   837→
   838→        window.addEventListener('popstate', async (e) => {
   839→            const state = e.state || loadFromUrl();
   840→            if (state.session) {
   841→                const fullProject = state.project.startsWith('-Users') ? state.project : getFullProjectName(state.project);
   842→                currentProject = fullProject;
   843→                currentConversation = state.session;
   844→                currentMessage = state.message || null;
   845→                await loadProjectSessions(fullProject, false);
   846→                const filePath = `data/projects/${fullProject}/${state.session}.jsonl`;
   847→                await loadConversation(filePath, false);
   848→                if (currentMessage) {
   849→                    scrollToMessage(currentMessage);
   850→                }
   851→            } else if (state.project) {
   852→                const fullProject = state.project.startsWith('-Users') ? state.project : getFullProjectName(state.project);
   853→                currentProject = fullProject;
   854→                currentConversation = null;
   855→                currentMessage = null;
   856→                await loadProjectSessions(fullProject, false);
   857→            } else {
   858→                currentProject = null;
   859→                currentConversation = null;
   860→                currentMessage = null;
   861→                renderProjectsList();
   862→            }
   863→        });
   864→
   865→        // Initialize from URL or load projects
   866→        (async () => {
   867→            const { project, session, message } = loadFromUrl();
   868→            await loadProjectsData();
   869→            if (project) {
   870→                const fullProject = project.startsWith('-Users') ? project : getFullProjectName(project);
   871→                if (session) {
   872→                    currentProject = fullProject;
   873→                    currentMessage = message || null;
   874→                    await loadProjectSessions(fullProject, false);
   875→                    const filePath = `data/projects/${fullProject}/${session}.jsonl`;
   876→                    await loadConversation(filePath, false);
   877→                    // Small delay to ensure DOM is fully rendered
   878→                    if (currentMessage) {
   879→                        setTimeout(() => scrollToMessage(currentMessage), 100);
   880→                    }
   881→                } else {
   882→                    await loadProjectSessions(fullProject, false);
   883→                }
   884→            } else {
   885→                renderProjectsList();
