            let gitBranch = '';
            let agentId = '';
            let isAgent = filename.includes('agent-');

            lines.forEach(line => {
                try {
                    const obj = JSON.parse(line);
                    if (obj.type === 'summary') {
                        summary = obj.summary;
                    } else if (obj.type === 'user' || obj.type === 'assistant') {
                        if (!sessionId && obj.sessionId) sessionId = obj.sessionId;
                        if (!gitBranch && obj.gitBranch) gitBranch = obj.gitBranch;
                        if (!agentId && obj.agentId) agentId = obj.agentId;

                        // Skip internal "Warmup" messages in agent sessions
                        if (isAgent && obj.type === 'user' && obj.message?.content === 'Warmup') {
                            return;
                        }
                        messages.push(obj);
                    } else if (obj.type === 'system') {
                        messages.push(obj);
                    }
                } catch (e) {}
            });

            const id = filename.split('/').pop().replace('.jsonl', '');
            currentConversation = id;
            conversations[id] = { filename, summary, sessionId, gitBranch, agentId, isAgent, messages };
        }

        function renderConversation() {
            const conv = conversations[currentConversation];
            if (!conv) return;

            // Use summary, or first user message, or filename as title
            let title = conv.summary;
            if (!title) {
                const firstUserMsg = conv.messages.find(m => m.type === 'user' && m.message?.content);
                if (firstUserMsg) {
                    const content = typeof firstUserMsg.message.content === 'string'
                        ? firstUserMsg.message.content
                        : firstUserMsg.message.content.find(c => c.type === 'text')?.text || '';
                    title = content.slice(0, 100) + (content.length > 100 ? '...' : '');
                }
            }
            document.getElementById('conversationTitle').textContent = title || conv.filename.split('/').pop();
            document.getElementById('conversationMeta').textContent = conv.gitBranch ? `Branch: ${conv.gitBranch}` : '';

            renderMessages();
        }

        function renderAgentInline(agentId, agentConv, msgUuid) {
            const title = agentConv.summary || `Agent ${agentId}`;
            const msgCount = agentConv.messages.length;

            // Reuse the same renderMessage function for consistency
            const messagesHtml = agentConv.messages.map(msg => renderMessage(msg, true)).join('');

            return `<div class="agent-inline-section"><div class="agent-inline-header" onclick="toggleAgentContent('${agentId}')"><span class="agent-icon">⚡</span><span class="agent-title">Agent ${agentId}</span><span class="agent-toggle">${msgCount} messages ▼</span></div><div class="agent-inline-content" id="agent-content-${agentId}">${messagesHtml}</div></div>`;
        }

        function toggleAgentContent(agentId) {
            const content = document.getElementById('agent-content-' + agentId);
            if (content) {
                content.classList.toggle('collapsed');
            }
        }

        function renderMessages() {
            const conv = conversations[currentConversation];
            if (!conv) return;

            // Render all messages - agents are inserted inline after Task tool results
            messagesContainer.innerHTML = conv.messages.map(msg => renderMessage(msg, true)).join('');
        }

        function renderMessage(msg, showTools) {
            const time = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'}) : '';

            // Check if this is a tool_result message (comes as type: "user" but is really tool output)
            const isToolResult = msg.type === 'user' &&
                Array.isArray(msg.message?.content) &&
                msg.message.content.some(c => c.type === 'tool_result');

            // Check if this is a meta message (isMeta: true indicates system-injected, not real user)
            const isMeta = msg.isMeta === true;

            // Check if this is a continuation message from context overflow (fallback text check)
            const isContinuation = msg.type === 'user' &&
                typeof msg.message?.content === 'string' &&
                msg.message.content.startsWith('This session is being continued from a previous conversation');

            const role = isToolResult ? 'tool' : ((isMeta || isContinuation) ? 'system' : (msg.type === 'user' ? 'user' : (msg.type === 'assistant' ? 'assistant' : 'system')));

            let content = '';

            // Handle system messages (different structure)
            if (msg.type === 'system') {
                const parts = [];
                if (msg.subtype) parts.push(`[${msg.subtype}]`);
                if (msg.hookInfos && msg.hookInfos.length > 0) {
                    parts.push(`Hooks: ${msg.hookInfos.map(h => h.command).join(', ')}`);
                }
                if (msg.stopReason) parts.push(`Stop: ${msg.stopReason}`);
                if (msg.level) parts.push(`Level: ${msg.level}`);
                content = escapeHtml(parts.join(' | ') || 'System event');
                // Show hook output/errors if present
                if (msg.hookErrors && msg.hookErrors.length > 0) {
                    content += '<div class="hook-output">' + msg.hookErrors.map(e => escapeHtml(e)).join('<hr>') + '</div>';
                }
            } else if (msg.message) {
                if (typeof msg.message.content === 'string') {
                    content = escapeHtml(msg.message.content);
                } else if (Array.isArray(msg.message.content)) {
                    content = msg.message.content.map(c => {
                        if (c.type === 'text') {
                            return escapeHtml(c.text);
                        } else if (c.type === 'image' && c.source) {
                            // Handle base64 images
                            const src = c.source.type === 'base64'
                                ? `data:${c.source.media_type};base64,${c.source.data}`
                                : c.source.url;
                            return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
                        } else if (c.type === 'tool_use' && showTools) {
                            return renderToolUse(c);
                        } else if (c.type === 'tool_result' && showTools) {
                            return renderToolResult(c, msg.uuid);
                        }
                        return '';
                    }).join('');
                }
            }

            if (!content.trim()) return '';

            // Build tooltip data with ALL non-id attributes
            const tooltipData = {};
            if (msg.message?.model) tooltipData.model = msg.message.model;
            if (msg.agentId) tooltipData.agent = msg.agentId;
            if (msg.gitBranch) tooltipData.branch = msg.gitBranch;
            if (msg.version) tooltipData.version = msg.version;
            if (msg.isSidechain !== undefined) tooltipData.sidechain = msg.isSidechain;
            if (msg.cwd) tooltipData.cwd = msg.cwd;
            if (msg.userType) tooltipData.userType = msg.userType;
            if (msg.message?.stop_reason) tooltipData.stop_reason = msg.message.stop_reason;
            if (msg.message?.usage) {
                const u = msg.message.usage;
                tooltipData.tokens = `in:${u.input_tokens || 0} out:${u.output_tokens || 0}`;
                if (u.cache_read_input_tokens) tooltipData.cache_read = u.cache_read_input_tokens;
                if (u.cache_creation_input_tokens) tooltipData.cache_create = u.cache_creation_input_tokens;
            }
            if (msg.parentUuid) tooltipData.parent = msg.parentUuid;
            if (msg.requestId) tooltipData.request = msg.requestId;

            const uuid = msg.uuid || '';
            const selectedClass = currentMessage === uuid ? ' selected' : '';

            // Check if content is only tool calls (no text)
            let isToolsOnly = false;
            if (Array.isArray(msg.message?.content)) {
                const hasText = msg.message.content.some(c => c.type === 'text' && c.text?.trim());
                const hasTools = msg.message.content.some(c => c.type === 'tool_use' || c.type === 'tool_result');
                isToolsOnly = hasTools && !hasText;
            }
            const toolsOnlyClass = isToolsOnly ? ' tools-only' : '';

            return `
                <div class="message ${role}${selectedClass}" data-tooltip='${JSON.stringify(tooltipData)}' data-uuid="${uuid}">
                    <div class="message-header">
                        <span class="message-role ${role}">${role}</span>
                        <span class="message-time">${time}</span>
                    </div>
                    <div class="message-content${toolsOnlyClass}">${content}</div>
                </div>
            `;
        }

        function renderToolUse(toolUse) {
            const name = toolUse.name;
            const input = toolUse.input || {};

            // Standard tool rendering
            let displayContent = '';

            switch (name) {
                case 'Read':
                    displayContent = `<span class="tool-param-label">file:</span> ${escapeHtml(input.file_path || '')}`;
                    if (input.offset || input.limit) {
                        displayContent += `<br><span class="tool-param-label">range:</span> ${input.offset || 0}-${(input.offset || 0) + (input.limit || '?')}`;
                    }
                    break;

                case 'Write':
                    displayContent = `<span class="tool-param-label">file:</span> ${escapeHtml(input.file_path || '')}`;
                    if (input.content) {
                        const preview = input.content.length > 500 ? input.content.slice(0, 500) + '...' : input.content;
                        displayContent += `<br><span class="tool-param-label">content:</span><pre class="tool-code-preview">${escapeHtml(preview)}</pre>`;
                    }
                    break;

                case 'Edit':
                    displayContent = `<span class="tool-param-label">file:</span> ${escapeHtml(input.file_path || '')}`;
                    if (input.old_string) {
                        const oldPreview = input.old_string.length > 200 ? input.old_string.slice(0, 200) + '...' : input.old_string;
                        displayContent += `<br><span class="tool-param-label">old:</span><pre class="tool-code-preview tool-old">${escapeHtml(oldPreview)}</pre>`;
                    }
                    if (input.new_string) {
                        const newPreview = input.new_string.length > 200 ? input.new_string.slice(0, 200) + '...' : input.new_string;
                        displayContent += `<br><span class="tool-param-label">new:</span><pre class="tool-code-preview tool-new">${escapeHtml(newPreview)}</pre>`;
                    }
                    break;

                case 'Bash':
                    displayContent = `<span class="tool-param-label">$</span> <code class="tool-command">${escapeHtml(input.command || '')}</code>`;
                    if (input.description) {
                        displayContent = `<span class="tool-description">${escapeHtml(input.description)}</span><br>` + displayContent;
                    }
                    if (input.timeout) {
                        displayContent += `<br><span class="tool-param-label">timeout:</span> ${input.timeout}ms`;
                    }
                    break;

                case 'Glob':
                    displayContent = `<span class="tool-param-label">pattern:</span> <code>${escapeHtml(input.pattern || '')}</code>`;
                    if (input.path) {
                        displayContent += `<br><span class="tool-param-label">path:</span> ${escapeHtml(input.path)}`;
                    }
                    break;

                case 'Grep':
                    displayContent = `<span class="tool-param-label">pattern:</span> <code>${escapeHtml(input.pattern || '')}</code>`;
                    if (input.path) {
                        displayContent += `<br><span class="tool-param-label">path:</span> ${escapeHtml(input.path)}`;
                    }
                    if (input.glob) {
                        displayContent += `<br><span class="tool-param-label">glob:</span> ${escapeHtml(input.glob)}`;
                    }
                    break;

                case 'Task':
                    // Track this Task tool call for matching with agent results
                    toolUseMap[toolUse.id] = { name: 'Task', input: input };
                    displayContent = `<span class="tool-param-label">type:</span> ${escapeHtml(input.subagent_type || '')}`;
                    if (input.description) {
                        displayContent += `<br><span class="tool-param-label">desc:</span> ${escapeHtml(input.description)}`;
                    }
                    if (input.prompt) {
                        const promptPreview = input.prompt.length > 300 ? input.prompt.slice(0, 300) + '...' : input.prompt;
                        displayContent += `<br><span class="tool-param-label">prompt:</span><pre class="tool-code-preview">${escapeHtml(promptPreview)}</pre>`;
                    }
                    break;

                case 'TodoWrite':
                    if (input.todos && Array.isArray(input.todos)) {
                        displayContent = input.todos.map(t => {
                            const icon = t.status === 'completed' ? '✓' : t.status === 'in_progress' ? '→' : '○';
                            return `<span class="todo-${t.status}">${icon} ${escapeHtml(t.content)}</span>`;
                        }).join('<br>');
                    }
                    break;

                case 'WebFetch':
                    displayContent = `<span class="tool-param-label">url:</span> <a href="${escapeHtml(input.url || '')}" target="_blank">${escapeHtml(input.url || '')}</a>`;
                    if (input.prompt) {
                        displayContent += `<br><span class="tool-param-label">prompt:</span> ${escapeHtml(input.prompt)}`;
                    }
                    break;

                case 'WebSearch':
                    displayContent = `<span class="tool-param-label">query:</span> "${escapeHtml(input.query || '')}"`;
                    break;

                case 'AskUserQuestion':
                    if (input.questions && Array.isArray(input.questions)) {
                        displayContent = input.questions.map(q => `<span class="tool-param-label">Q:</span> ${escapeHtml(q.question)}`).join('<br>');
                    }
                    break;

                case 'NotebookEdit':
                    displayContent = `<span class="tool-param-label">notebook:</span> ${escapeHtml(input.notebook_path || '')}`;
                    if (input.cell_type) {
                        displayContent += `<br><span class="tool-param-label">cell type:</span> ${escapeHtml(input.cell_type)}`;
                    }
                    if (input.edit_mode) {
                        displayContent += `<br><span class="tool-param-label">mode:</span> ${escapeHtml(input.edit_mode)}`;
                    }
                    break;

                // MCP Puppeteer tools
                case 'mcp__puppeteer__puppeteer_navigate':
                    displayContent = `<span class="tool-param-label">url:</span> <a href="${escapeHtml(input.url || '')}" target="_blank" class="tool-url">${escapeHtml(input.url || '')}</a>`;
                    break;

                case 'mcp__puppeteer__puppeteer_screenshot':
                    displayContent = `<span class="tool-param-label">name:</span> ${escapeHtml(input.name || '')}`;
                    if (input.width || input.height) {
                        displayContent += `<br><span class="tool-param-label">size:</span> ${input.width || '?'}x${input.height || '?'}`;
                    }
                    if (input.selector) {
                        displayContent += `<br><span class="tool-param-label">selector:</span> <code>${escapeHtml(input.selector)}</code>`;
                    }
                    break;

                case 'mcp__puppeteer__puppeteer_click':
                case 'mcp__puppeteer__puppeteer_hover':
                    displayContent = `<span class="tool-param-label">selector:</span> <code>${escapeHtml(input.selector || '')}</code>`;
                    break;

                case 'mcp__puppeteer__puppeteer_fill':
                    displayContent = `<span class="tool-param-label">selector:</span> <code>${escapeHtml(input.selector || '')}</code>`;
                    displayContent += `<br><span class="tool-param-label">value:</span> "${escapeHtml(input.value || '')}"`;
                    break;

                case 'mcp__puppeteer__puppeteer_select':
                    displayContent = `<span class="tool-param-label">selector:</span> <code>${escapeHtml(input.selector || '')}</code>`;
                    displayContent += `<br><span class="tool-param-label">value:</span> "${escapeHtml(input.value || '')}"`;
                    break;

                case 'mcp__puppeteer__puppeteer_evaluate':
                    const scriptPreview = (input.script || '').length > 300 ? input.script.slice(0, 300) + '...' : input.script;
                    displayContent = `<span class="tool-param-label">script:</span><pre class="tool-code-preview">${escapeHtml(scriptPreview || '')}</pre>`;
                    break;

                default:
                    // For unknown tools or MCP tools, show JSON
                    const jsonStr = typeof input === 'object' ? JSON.stringify(input, null, 2) : input;
                    displayContent = `<pre class="tool-json">${escapeHtml(jsonStr)}</pre>`;
            }

            return `<div class="tool-use"><div class="tool-header">${escapeHtml(name)}</div><div class="tool-input">${displayContent}</div></div>`;
        }

        function renderToolResult(toolResult, msgUuid) {
            let content = '';
            let rawContent = '';

            if (typeof toolResult.content === 'string') {
                content = escapeHtml(toolResult.content);
                rawContent = toolResult.content;
            } else if (Array.isArray(toolResult.content)) {
                content = toolResult.content.map(c => {
                    if (c.type === 'image' && c.source) {
                        const src = c.source.type === 'base64'
                            ? `data:${c.source.media_type};base64,${c.source.data}`
                            : c.source.url;
                        return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
                    }
                    if (c.text) rawContent += c.text;
                    return c.text ? escapeHtml(c.text) : '';
                }).join('\n');
            }

            const isError = toolResult.is_error === true;
            const errorClass = isError ? ' error' : '';
            const headerText = isError ? 'Hook Error' : 'Output';

            let resultHtml = `<div class="tool-result${errorClass}"><div class="tool-result-header">${headerText}</div><div class="tool-result-content">${content}</div></div>`;

            // Check if this is a Task tool result - if so, insert agent inline
            const toolUseId = toolResult.tool_use_id;
            const toolInfo = toolUseMap[toolUseId];
            if (toolInfo && toolInfo.name === 'Task') {
                // Try to find matching agent by looking for agent ID in the result
                // Task results often contain "Agent ID: xxx" or similar
                const agentIdMatch = rawContent.match(/agent[_-]?(?:id)?[:\s]*([a-f0-9]{8})/i) ||
                                     rawContent.match(/([a-f0-9]{8})/);

                // Also try to match by finding any unrendered agent
                let matchedAgentId = null;
                if (agentIdMatch) {
                    const potentialId = agentIdMatch[1];
                    if (loadedAgentConversations[potentialId] && !renderedAgents.has(potentialId)) {
                        matchedAgentId = potentialId;
                    }
                }

                // If no match by ID, try to get next unrendered agent in order
                if (!matchedAgentId) {
                    for (const agentId of Object.keys(loadedAgentConversations)) {
                        if (!renderedAgents.has(agentId)) {
                            matchedAgentId = agentId;
                            break;
                        }
                    }
                }

                if (matchedAgentId && loadedAgentConversations[matchedAgentId]) {
                    renderedAgents.add(matchedAgentId);
                    resultHtml += renderAgentInline(matchedAgentId, loadedAgentConversations[matchedAgentId], msgUuid);
                }
            }

            return resultHtml;
        }

        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Mouse-following tooltip
        const mouseTooltip = document.getElementById('mouseTooltip');

        document.addEventListener('mousemove', (e) => {
            const msgEl = e.target.closest('.message[data-tooltip]');
            if (msgEl) {
                const data = JSON.parse(msgEl.dataset.tooltip);
                if (Object.keys(data).length > 0) {
                    // Build tooltip content
                    let html = '';
                    for (const [key, value] of Object.entries(data)) {
                        html += `<div class="tooltip-row"><span class="tooltip-key">${key}:</span><span class="tooltip-value">${value}</span></div>`;
                    }
                    mouseTooltip.innerHTML = html;
                    mouseTooltip.style.display = 'block';

                    // Position near cursor
                    let x = e.clientX + 15;
                    let y = e.clientY + 15;

                    // Keep tooltip on screen
                    const rect = mouseTooltip.getBoundingClientRect();
                    if (x + rect.width > window.innerWidth) {
                        x = e.clientX - rect.width - 10;
                    }
                    if (y + rect.height > window.innerHeight) {
                        y = e.clientY - rect.height - 10;
                    }

                    mouseTooltip.style.left = x + 'px';
                    mouseTooltip.style.top = y + 'px';
                } else {
                    mouseTooltip.style.display = 'none';
                }
            } else {
                mouseTooltip.style.display = 'none';
            }
        });

        document.addEventListener('mouseout', (e) => {
            if (!e.relatedTarget || !document.body.contains(e.relatedTarget)) {
                mouseTooltip.style.display = 'none';
            }
        });

        // Click on message to select it and update URL
        messagesContainer.addEventListener('click', (e) => {
            const msgEl = e.target.closest('.message[data-uuid]');
            if (msgEl && msgEl.dataset.uuid) {
                // If in user-only mode and clicking a user message, toggle expansion
                if (userOnlyMode && msgEl.classList.contains('user')) {
                    toggleUserMessageExpansion(msgEl);
                }
                // Remove previous selection
                document.querySelectorAll('.message.selected').forEach(el => el.classList.remove('selected'));
                // Select this message
                msgEl.classList.add('selected');
                currentMessage = msgEl.dataset.uuid;
                updateUrl();
            }
        });

        function scrollToMessage(uuid) {
            // Find the message (agent sections are expanded by default now)
            const msgEl = document.querySelector(`.message[data-uuid="${uuid}"]`);
            if (msgEl) {
                // Make sure parent agent section is not collapsed
                const parentAgentContent = msgEl.closest('.agent-inline-content');
                if (parentAgentContent) {
                    parentAgentContent.classList.remove('collapsed');
                }

                msgEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
                msgEl.classList.add('selected');
            }
        }
    </script>
</body>

#!/usr/bin/env python3
"""Simple server to browse Claude Code conversation history."""

import http.server
import json
import os
import socketserver
from pathlib import Path
from urllib.parse import parse_qs, urlparse

DEFAULT_PORT = 44043
DATA_DIR = Path(__file__).parent / "data" / "projects"


def find_available_port(start_port: int, max_attempts: int = 100) -> int:
    """Find an available port starting from start_port."""
    import socket

    for port in range(start_port, start_port + max_attempts):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.bind(("", port))
                return port
        except OSError:
            continue
    raise RuntimeError(
        f"No available port found in range {start_port}-{start_port + max_attempts}"
    )


class ConversationHandler(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)

        if parsed.path == "/api/projects":
            self.send_projects_list()
        elif parsed.path == "/api/sessions":
            query = parse_qs(parsed.query)
            project = query.get("project", [""])[0]
            self.send_sessions_list(project)
        elif parsed.path == "/api/conversation":
            query = parse_qs(parsed.query)
            file_path = query.get("file", [""])[0]
            self.send_conversation(file_path)
        else:
            super().do_GET()

    def send_json(self, data):
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def send_projects_list(self):
        projects = []
        if DATA_DIR.exists():
            for item in sorted(DATA_DIR.iterdir()):
                if item.is_dir():
                    # Count jsonl files efficiently using os.listdir
                    try:
                        files = os.listdir(item)
                        session_count = sum(1 for f in files if f.endswith(".jsonl"))
                        if session_count > 0:
                            projects.append(
                                {
                                    "name": item.name,
                                    "path": str(item),
                                    "sessionCount": session_count,
                                }
                            )
                    except OSError:
                        pass
        self.send_json(projects)

    def send_sessions_list(self, project):
        sessions = []
        project_path = DATA_DIR / project
        if project_path.exists():
            for item in sorted(
                project_path.glob("*.jsonl"), key=os.path.getmtime, reverse=True
            ):
                summary = self.get_conversation_summary(item)
                sessions.append(
                    {
                        "name": item.name,
                        "path": str(item),
                        "summary": summary,
                        "modified": os.path.getmtime(item),
                    }
                )
        self.send_json(sessions)

    def get_conversation_summary(self, file_path):
        try:
            with open(file_path) as f:
                first_line = f.readline()
                data = json.loads(first_line)
                if data.get("type") == "summary":
                    return data.get("summary", "")
        except (json.JSONDecodeError, FileNotFoundError, KeyError):
            pass
        return ""

    def send_conversation(self, file_path):
        try:
            with open(file_path) as f:
                content = f.read()
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(content.encode())
        except FileNotFoundError:
            self.send_error(404, "File not found")


if __name__ == "__main__":
    os.chdir(Path(__file__).parent)
    port = find_available_port(DEFAULT_PORT)
    with socketserver.TCPServer(("", port), ConversationHandler) as httpd:
        print(f"Server running at http://localhost:{port}")
        print(f"Open http://localhost:{port}")
        httpd.serve_forever()

